using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public sealed class QualityEvaluationTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    public static IEnumerable<object[]> GoldenCases()
    {
        var json = File.ReadAllText(GoldenPath);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        foreach (var c in cases)
        {
            yield return new object[] { c.Id, c.UserMessage, c.ExpectedTraits };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task EvaluateQuality(string id, string userMessage, string[] expectedTraits)
    {
        // Arrange
        var rubric = await File.ReadAllTextAsync(RubricPath);

        // Act — invoke the agent under test (placeholder: replace with actual agent call)
        var response = await InvokeAgentAsync(userMessage);

        // Assert — verify expected traits are present in the response
        Assert.NotNull(response);
        Assert.False(string.IsNullOrWhiteSpace(response),
            $"Case '{id}': agent returned empty response for: {userMessage}");

        foreach (var trait in expectedTraits)
        {
            Assert.True(
                response.Contains(trait, StringComparison.OrdinalIgnoreCase),
                $"Case '{id}': expected trait '{trait}' not found in response.");
        }
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // TODO: Replace with actual agent invocation via the AppHost.
        // Example: use HttpClient to call the running agent endpoint.
        throw new NotImplementedException(
            "Wire up the agent endpoint from MyApp.AppHost to complete the evaluation harness.");
    }
}

public sealed record GoldenCase
{
    public string Id { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public string[] ExpectedTraits { get; init; } = [];
}

